tool_input.command:
$env:PYTHONIOENCODING='utf-8'
Write-Output "== screen_sz 财务取数(report_period) =="
Select-String -Path 'D:\repository\数据湖\分析产出\screen_sz.py' -Pattern 'financial_statement_items|report_period|announce_date|con.execute' -Context 0,2 | Select-Object -First 6 | ForEach-Object {"L$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(90,$_.Line.Trim().Length)))"}

$env:PYTHONIOENCODING='utf-8'
Write-Output "== screen_sz BASE 定义/用法 =="
Select-String -Path 'D:\repository\数据湖\分析产出\screen_sz.py' -Pattern "BASE\s*=|BASE\b" | Select-Object -First 6 | ForEach-Object {"L$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(80,$_.Line.Trim().Length)))"}

$env:PYTHONIOENCODING='utf-8'
Write-Output "== L136 所在函数(向上找 def) =="
$c=Get-Content 'D:\repository\数据湖\分析产出\screen_sz.py'
for($i=135;$i -ge 80;$i--){ if($c[$i] -match '^\s*def '){ "函数定义 L$($i+1): $($c[$i].Trim())"; break } }
Write-Output "== 该函数内 base 是否在作用域(前面有 base= 吗) =="
for($i=80;$i -lt 137;$i++){ if($c[$i] -match 'base\s*=' -or $c[$i] -match 'def .*base'){ "L$($i+1): $($c[$i].Trim())" } }

$env:PYTHONIOENCODING='utf-8'
$c=Get-Content 'D:\repository\数据湖\分析产出\screen_sz.py'
Write-Output "== 1-136 行里 base/BASE 赋值 =="
for($i=0;$i -lt 136;$i++){ if($c[$i] -match '\bbase\b\s*=|\bBASE\b\s*='){ "L$($i+1): $($c[$i].Trim())" } }
Write-Output "== 是否有全局 BASE =="
Select-String -Path 'D:\repository\数据湖\分析产出\screen_sz.py' -Pattern "BASE\s*=" | ForEach-Object {"L$($_.LineNumber): $($_.Line.Trim())"}

$env:PYTHONIOENCODING='utf-8'
$c=Get-Content 'D:\repository\数据湖\分析产出\screen_sz.py'
# 找 L136(索引135) 上方最近的 def 及参数
for($i=135;$i -ge 0;$i--){ if($c[$i] -match '^def |^    def |^\s*def '){ "def at L$($i+1): $($c[$i].Trim())"; break } }
Write-Output "== 该函数附近L80-136 的 def 列表 =="
for($i=60;$i -lt 136;$i++){ if($c[$i] -match 'def '){ "L$($i+1): $($c[$i].Trim())" } }

$env:PYTHONIOENCODING='utf-8'
$c=Get-Content 'D:\repository\数据湖\分析产出\screen_sz.py'
for($i=371;$i -ge 290;$i--){ if($c[$i] -match '^def |def .*\(' ){ "L$($i+1): $($c[$i].Trim())"; break } }
Write-Output "== 主函数签名附近 base 用法 =="
for($i=290;$i -lt 400;$i++){ if($c[$i] -match '\bbase\b'){ "L$($i+1): $($c[$i].Trim().Substring(0,[Math]::Min(80,$c[$i].Trim().Length)))"; if($i -gt 300){break} } }

